import products from './products.json' with { type: 'json' };

const INVENTORY_SEARCH_TOOL = {
  name: 'inventory_search',
  description: 'Search the product inventory by name. Returns matching products, limited in number.',
  inputSchema: {
    type: 'object',
    properties: {
      query: {
        type: 'string',
        description: 'The search term to match against product names (case-insensitive).'
      },
      limit: {
        type: 'integer',
        minimum: 1,
        maximum: 10,
        description: 'Maximum number of results to return (1-10). Defaults to 10.'
      }
    },
    required: ['query'],
    additionalProperties: false
  }
};

export async function listTools() {
  return [INVENTORY_SEARCH_TOOL];
}

export async function callTool(name, args) {
  if (name !== 'inventory_search') {
    throw new Error(`Unknown tool: ${name}`);
  }

  if (typeof args !== 'object' || args === null || Array.isArray(args)) {
    throw new Error('Invalid arguments: expected an object');
  }

  const allowed = new Set(['query', 'limit']);
  for (const key of Object.keys(args)) {
    if (!allowed.has(key)) {
      throw new Error(`Invalid argument "${key}": unknown property`);
    }
  }

  const { query, limit } = args;

  if (typeof query !== 'string') {
    throw new Error('Invalid argument "query": expected a string');
  }

  if (limit !== undefined) {
    if (typeof limit !== 'number' || !Number.isInteger(limit) || limit < 1 || limit > 10) {
      throw new Error('Invalid argument "limit": expected an integer between 1 and 10');
    }
  }

  const max = limit !== undefined ? limit : 10;
  const needle = query.toLowerCase();

  const matches = products
    .filter((p) => p.name.toLowerCase().includes(needle))
    .slice(0, max);

  const text = matches.length > 0
    ? matches.map((p) => `${p.id}: ${p.name}`).join('\n')
    : 'No products found.';

  return {
    content: [{ type: 'text', text }]
  };
}
